import zones from "../../../testdata/timezones.json";

/** Every zone the Settings picker offers, UTC first. The list is testdata/timezones.json, generated by
 * scripts/gen-timezones.mjs; server/timezones_test.go checks that each entry loads against the embedded tzdata. */
export const TIMEZONES: readonly string[] = zones;

/** Zones matching what the owner typed: case-insensitive, with a space or underscore treated alike, so "new
 * york" finds America/New_York and "Los" finds America/Los_Angeles. Prefix matches of the city part and of the
 * whole name come first. An empty query lists everything. */
export function filterTimezones(query: string, list: readonly string[] = TIMEZONES): string[] {
  const q = query.trim().toLowerCase().replace(/[\s_]+/g, "_");
  if (q === "") return [...list];
  const starts: string[] = [];
  const rest: string[] = [];
  for (const z of list) {
    const lower = z.toLowerCase();
    if (!lower.includes(q)) continue;
    const city = lower.slice(lower.lastIndexOf("/") + 1);
    (lower.startsWith(q) || city.startsWith(q) ? starts : rest).push(z);
  }
  return [...starts, ...rest];
}

/** The browser's own zone, or "" when it can't say. */
export function deviceTimezone(): string {
  try {
    return Intl.DateTimeFormat().resolvedOptions().timeZone || "";
  } catch {
    return "";
  }
}
